class Solution:
    def convertToDigits(self, s: str) -> str:
        words = {"zero":"0","one":"1","two":"2","three":"3","four":"4",
                 "five":"5","six":"6","seven":"7","eight":"8","nine":"9"}
        res = []
        i, n = 0, len(s)
        while i < n:
            for L in (3, 4, 5):
                if s[i:i+L] in words:
                    res.append(words[s[i:i+L]])
                    i += L
                    break
            else:
                i += 1
        return "".join(res)

