class Solution:
    def convertToDigits(self, s: str) -> str:
        words = {"zero":0,"one":1,"two":2,"three":3,"four":4,"five":5,"six":6,"seven":7,"eight":8,"nine":9}
        root = {}
        for w, d in words.items():
            cur = root
            for ch in w:
                cur = cur.setdefault(ch, {})
            cur['$'] = d
        res, i, n = [], 0, len(s)
        while i < n:
            cur, j, hit = root, i, None
            while j < n and s[j] in cur:
                cur = cur[s[j]]
                j += 1
                if '$' in cur:
                    hit = cur['$']
            if hit is None:
                i += 1
            else:
                res.append(str(hit))
                i = j
        return "".join(res)

