class Solution {
public:
    string convertToDigits(string s) {
        struct Node { unordered_map<char,Node*> ch; int dig = -1; };
        Node* root = new Node();
        vector<string> ws{"zero","one","two","three","four","five","six","seven","eight","nine"};
        for (int d = 0; d < 10; d++) {
            Node* cur = root;
            for (char c : ws[d]) {
                if (!cur->ch.count(c)) cur->ch[c] = new Node();
                cur = cur->ch[c];
            }
            cur->dig = d;
        }
        string res;
        int i = 0, n = s.size();
        while (i < n) {
            Node* cur = root; int j = i, hit = -1;
            while (j < n && cur->ch.count(s[j])) {
                cur = cur->ch[s[j++]];
                if (cur->dig >= 0) hit = cur->dig;
            }
            if (hit < 0) i++;
            else { res += char('0' + hit); i = j; }
        }
        return res;
    }
};

