class Solution {
    public String convertToDigits(String s) {
        class Node { java.util.Map<Character,Node> ch = new java.util.HashMap<>(); int dig = -1; }
        Node root = new Node();
        String[] ws = {"zero","one","two","three","four","five","six","seven","eight","nine"};
        for (int d = 0; d < 10; d++) {
            Node cur = root;
            for (char c : ws[d].toCharArray()) cur = cur.ch.computeIfAbsent(c, x -> new Node());
            cur.dig = d;
        }
        StringBuilder res = new StringBuilder();
        int i = 0, n = s.length();
        while (i < n) {
            Node cur = root; int j = i, hit = -1;
            while (j < n && cur.ch.containsKey(s.charAt(j))) {
                cur = cur.ch.get(s.charAt(j++));
                if (cur.dig >= 0) hit = cur.dig;
            }
            if (hit < 0) i++;
            else { res.append((char)('0' + hit)); i = j; }
        }
        return res.toString();
    }
}

